import pathlib,json,sys
paths=json.loads(sys.argv[1]); failures=[]
for path in paths:
 data=pathlib.Path(path).read_bytes()
 if not data.endswith(b"\n"): failures.append(path+": missing final newline")
 for number,line in enumerate(data.splitlines(),1):
  if line.rstrip(b" \t")!=line: failures.append(path+":"+str(number)+": trailing whitespace")
print(json.dumps({"checkedPaths":len(paths),"failures":failures}))
sys.exit(1 if failures else 0)
